const d = $input.first().json;
const intent = d.intentResult;
let contextual = "";
if (intent === 'wants_consultation') {
  contextual = "Great! You're almost there. To confirm your consultation, please complete the payment below.\n\n";
} else if (intent === 'rebook_intent') {
  contextual = "For rebooking, please complete the pending payment first.\n\n";
} else {
  contextual = "Happy to help! Once your payment is confirmed, Dr. Chinmay will be ready for your consultation.\n\n";
}
const PAYMENT_DETAILS = "💰 *Payment Details*\nSend ₹500 via GPay / PhonePe / any UPI app to:\n*+91-9653240263 (Chinmay Mujumdar)*\n\nOnce you've paid, tap the button below to confirm.";
return [{ json: {
  phoneNumber: d.phoneNumber,
  messageType: 'interactive',
  interactivePayload: {
    type: 'button',
    body: { text: contextual + PAYMENT_DETAILS },
    action: { buttons: [ { type: 'reply', reply: { id: 'payment_completed', title: 'Payment Completed ✓' } } ] }
  }
} }];

const geminiResp = $input.first().json;
const prevData = $('Prepare Gemini Response Prompt').first().json;
let reply = "Thank you for your message! For questions about our Vedic astrology consultation, feel free to ask.";
